internal fun loadEmbeddedModuleBitmap(highlights: Boolean): ImageBitmap? {
    return runCatching {
        val encoded = if (highlights) HIGHLIGHTS_PNG else BODY_PNG
        val bytes = Base64.decode(encoded, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size)?.asImageBitmap()
    }.getOrNull()
}
